<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ARTIFACT: Museum Night</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<style>
:root{
  --bg:#070506;
  --velvet:#1a0710;
  --burgundy:#3a0f1d;
  --navy:#07111f;
  --gold:#d6ad60;
  --softgold:#f3d79b;
  --ivory:#f8efe2;
  --muted:#b9a999;
  --panel:rgba(255,244,220,0.06);
  --border:rgba(214,173,96,0.28);
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  background:var(--bg);
  color:var(--ivory);
  font-family:Inter,system-ui,Segoe UI,sans-serif;
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
  overflow-x:hidden;
}
h1,h2,h3{font-family:Georgia,Times New Roman,serif;font-weight:400;letter-spacing:.01em}
a{color:inherit;text-decoration:none}
img{max-width:100%;display:block}
.grain::before{
  content:"";position:fixed;inset:0;pointer-events:none;opacity:.04;
  background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  z-index:9999;
}
.container{width:min(1200px,92%);margin:auto}
.navbar{
  position:sticky;top:0;z-index:1000;
  backdrop-filter:blur(12px);
  background:rgba(7,5,6,0.7);
  border-bottom:1px solid var(--border);
}
.nav-inner{display:flex;align-items:center;justify-content:space-between;padding:18px 0}
.logo{font-family:Georgia,serif;font-size:22px;letter-spacing:.14em;color:var(--ivory)}
.nav-links{display:flex;gap:28px;font-size:14px;text-transform:uppercase;letter-spacing:.12em}
.nav-links a{opacity:.8}
.nav-links a.active,.nav-links a:hover{opacity:1;color:var(--softgold)}

